{
  "name": "Aim-TTI EL302P 单路直流电源",
  "name_en": "Aim-TTI EL302P Single-Output DC Power Supply",
  "manufacturer": "Aim-TTI",
  "description": "Aim-TTI EL302P 是一台单路可编程直流电源，可提供可调电压与电流并控制输出开关。它常用于电子电路供电、器件调试、台式测试以及一般实验室电源应用。",
  "description_en": "The Aim-TTI EL302P is a single-output programmable DC power supply that provides adjustable voltage and current with controllable output on/off. It is commonly used for powering electronic circuits, device debugging, bench testing, and general laboratory power applications.",
  "tag_hints": [
    "DC power supply",
    "single-output PSU",
    "programmable power supply",
    "adjustable voltage",
    "current limit control",
    "bench electronics testing"
  ],
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取/设置输出电流设定值。",
      "description_en": "Get/set the output current setting."
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置输出开关状态。",
      "description_en": "Get/set the output on/off state."
    },
    {
      "action_name": "auto-reset",
      "description": "将电源复位到默认上电设置（1.00 V、1.00 A、输出关闭）。",
      "description_en": "Reset the power supply to its default power-up settings (1.00 V, 1.00 A, output off)."
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置输出电压设定值。",
      "description_en": "Get/set the output voltage setting."
    },
    {
      "action_name": "auto-name",
      "description": "获取仪器名称。",
      "description_en": "Get the instrument name."
    },
    {
      "action_name": "auto-channel",
      "description": "获取通道信息。",
      "description_en": "Get the channel information."
    }
  ]
}

